<template><section class="flex h-full min-h-0 flex-col overflow-hidden bg-background"><header class="flex min-h-14 items-center gap-2 border-b px-4"><Button variant="ghost" size="sm" @click="router.back()"><ArrowLeft class="mr-1 h-4 w-4"/>{{ t('common.back') }}</Button><h1 class="font-semibold">Create review</h1></header><div class="min-h-0 flex-1 overflow-auto p-4"><div class="mx-auto max-w-3xl space-y-5"><article v-if="context" class="rounded-lg border bg-card p-5"><div class="flex items-end justify-between"><div><p class="text-sm text-muted-foreground">System facts · last {{ windowDays }} days</p><p class="mt-1 text-2xl font-semibold">{{ context.overallProgress.endPercentage }}%</p></div><span class="text-sm" :class="context.overallProgress.deltaPercentage>=0?'text-emerald-600':'text-destructive'">{{ signed(context.overallProgress.deltaPercentage) }}</span></div><Progress class="mt-4" :model-value="context.overallProgress.endPercentage"/><div class="mt-4 grid gap-2 sm:grid-cols-3"><div class="rounded-md bg-muted p-3"><p class="text-xs text-muted-foreground">Records</p><p class="font-medium">{{ context.summary.recordCount }}</p></div><div class="rounded-md bg-muted p-3"><p class="text-xs text-muted-foreground">Manual</p><p class="font-medium">{{ context.summary.manualRecordCount }}</p></div><div class="rounded-md bg-muted p-3"><p class="text-xs text-muted-foreground">Task contributions</p><p class="font-medium">{{ context.summary.taskContributionCount }}</p></div></div><div class="mt-4 space-y-2"><div v-for="kr in context.keyResults" :key="kr.keyResultId" class="rounded-md border p-3"><div class="flex justify-between text-sm"><span>{{ kr.title }}</span><span>{{ kr.startPercentage }}% → {{ kr.endPercentage }}%</span></div><Progress class="mt-2" :model-value="kr.endPercentage"/></div></div></article><div class="space-y-2"><Label>Reflection</Label><Textarea v-model="reflection" class="min-h-32" placeholder="What happened, what did you learn?"/></div><div class="space-y-2"><Label>Challenges</Label><Textarea v-model="challenges" class="min-h-20"/></div><div class="space-y-2"><Label>Adjustments</Label><Textarea v-model="adjustments" class="min-h-20"/></div><div class="flex justify-end"><Button :disabled="!reflection.trim()||saving" @click="submit">Save review</Button></div></div></div></section></template>
<script setup lang="ts">
import { onMounted,ref } from 'vue';import { useRoute,useRouter } from 'vue-router';import { useI18n } from 'vue-i18n';import { ArrowLeft } from '@lucide/vue';import { Button,Label,Progress,Textarea } from '@memoflow/ui-vue-shadcn';import type { GoalReviewSystemContext } from '@memoflow/contracts/goal';import { GOAL_SERVICE_KEY } from '../../../di/keys';import { useStrictInject } from '../../../shared/utils/useStrictInject';import { useGoal } from '../composables/useGoal';
const route=useRoute();const router=useRouter();const {t}=useI18n();const service=useStrictInject(GOAL_SERVICE_KEY,'GoalService');const {getGoalAggregateView,createReview}=useGoal();const goalId=String(route.params.goalId??'');const windowDays=7;const context=ref<GoalReviewSystemContext|null>(null);const reflection=ref('');const challenges=ref('');const adjustments=ref('');const saving=ref(false);onMounted(async()=>{await getGoalAggregateView(goalId);const result=await service.getGoalReviewContext(goalId,windowDays);if(result.ok)context.value=result.data;});async function submit(){saving.value=true;try{const review=await createReview(goalId,{reflection:reflection.value,challenges:challenges.value.trim()||null,adjustments:adjustments.value.trim()||null,windowDays});if(review)await router.push({name:'goal-review-detail',params:{goalId,reviewId:review.id}});}finally{saving.value=false;}}function signed(v:number){return `${v>=0?'+':''}${Math.round(v*100)/100}%`;}
</script>
